"""Offline DNS model-based regression workbench.

Implements input validation, the frozen local resolution model, observation
adjudication, and exact minimum-cost diagnostic basis selection.
"""
import ipaddress
import json
import math
import re
import sys

MAX_BYTES = 8 * 1024 * 1024
TYPES = ("A", "AAAA", "TXT", "CNAME")
RCODES = ("NOERROR", "NXDOMAIN", "SERVFAIL", "REFUSED")
ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")
A_OCTET_RE = re.compile(r"(?:0|[1-9][0-9]{0,2})\Z")


class Invalid(Exception):
    pass


# ---------------------------------------------------------------- name helpers
def valid_name(s):
    """Return canonical (lowercased) name, or None if invalid."""
    if not isinstance(s, str):
        return None
    if s == ".":
        return "."
    if not s.endswith("."):
        return None
    body = s[:-1]
    if body == "":
        return None
    labels = body.split(".")
    wire = 1  # root byte
    for lab in labels:
        if lab == "":
            return None
        if lab == "*":
            pass
        else:
            if not (1 <= len(lab) <= 63):
                return None
            for c in lab:
                if not (c.isascii() and (c.isalnum() or c in "-_")):
                    return None
        wire += len(lab) + 1
    if wire > 255:
        return None
    return s.lower()


def label_tuple(name):
    if name == ".":
        return ()
    return tuple(name[:-1].split("."))


def label_count(name):
    if name == ".":
        return 0
    return len(label_tuple(name))


def parent(name):
    if name == ".":
        return None
    i = name.find(".")
    rest = name[i + 1:]
    return rest if rest else "."


def at_or_below(name, origin):
    if origin == ".":
        return True
    nl = label_tuple(name)
    ol = label_tuple(origin)
    if len(nl) < len(ol):
        return False
    return nl[-len(ol):] == ol


# ---------------------------------------------------------------- data helpers
def canon_A(d):
    if not isinstance(d, str):
        raise Invalid
    parts = d.split(".")
    if len(parts) != 4:
        raise Invalid
    for p in parts:
        if not A_OCTET_RE.fullmatch(p):
            raise Invalid
        if int(p) > 255:
            raise Invalid
    return d


def canon_AAAA(d):
    if not isinstance(d, str):
        raise Invalid
    if "%" in d:
        raise Invalid
    try:
        ip = ipaddress.IPv6Address(d)
    except Exception:
        raise Invalid
    return ip.compressed


def canon_TXT(d):
    if not isinstance(d, str):
        raise Invalid
    if len(d) > 256:
        raise Invalid
    for ch in d:
        o = ord(ch)
        if o < 0x20 or o > 0x7E:
            raise Invalid
    return d


def canon_CNAME(d):
    n = valid_name(d)
    if n is None:
        raise Invalid
    return n


def canon_data(t, d):
    if t == "A":
        return canon_A(d)
    if t == "AAAA":
        return canon_AAAA(d)
    if t == "TXT":
        return canon_TXT(d)
    if t == "CNAME":
        return canon_CNAME(d)
    raise Invalid


def parse_record(obj):
    if not isinstance(obj, dict):
        raise Invalid
    if set(obj.keys()) != {"owner", "type", "data"}:
        raise Invalid
    owner = valid_name(obj["owner"])
    if owner is None:
        raise Invalid
    t = obj["type"]
    if not isinstance(t, str) or t not in TYPES:
        raise Invalid
    data = canon_data(t, obj["data"])
    return (owner, t, data)


def valid_id(x):
    return isinstance(x, str) and ID_RE.fullmatch(x) is not None


# ---------------------------------------------------------------- json handling
def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise ValueError("duplicate key")
        d[k] = v
    return d


def _parse_float(s):
    v = float(s)
    if not math.isfinite(v):
        raise ValueError("nonfinite")
    return v


def _parse_constant(s):
    raise ValueError("nonfinite")


def check_depth(root):
    # Count nested object/array containers; root container is depth 1.
    stack = [(root, 1)]
    while stack:
        node, d = stack.pop()
        if isinstance(node, dict):
            if d > 32:
                return False
            for v in node.values():
                if isinstance(v, (dict, list)):
                    stack.append((v, d + 1))
        elif isinstance(node, list):
            if d > 32:
                return False
            for v in node:
                if isinstance(v, (dict, list)):
                    stack.append((v, d + 1))
    return True


# ---------------------------------------------------------------- validation
def build_zones(zones):
    if not isinstance(zones, list):
        raise Invalid
    if len(zones) > 16:
        raise Invalid
    parsed_zones = []
    origins = set()
    total_entries = 0
    for z in zones:
        if not isinstance(z, dict):
            raise Invalid
        if set(z.keys()) != {"origin", "records"}:
            raise Invalid
        origin = valid_name(z["origin"])
        if origin is None:
            raise Invalid
        if origin in origins:
            raise Invalid
        origins.add(origin)
        recs = z["records"]
        if not isinstance(recs, list):
            raise Invalid
        total_entries += len(recs)
        if total_entries > 1024:
            raise Invalid
        parsed = []
        for r in recs:
            parsed.append(parse_record(r))
        for (o, t, d) in parsed:
            if not at_or_below(o, origin):
                raise Invalid
        parsed_zones.append((origin, parsed))

    zone_structs = []
    for origin, parsed in parsed_zones:
        group = {}
        for (o, t, d) in parsed:
            group.setdefault(o, {}).setdefault(t, set()).add(d)
        for owner, typemap in group.items():
            if "CNAME" in typemap:
                if owner == origin:
                    raise Invalid
                if len(typemap) != 1:
                    raise Invalid
                if len(typemap["CNAME"]) != 1:
                    raise Invalid
            for t, ds in typemap.items():
                if len(ds) > 64:
                    raise Invalid
        recs = {}
        for owner, typemap in group.items():
            recs[owner] = {t: sorted(ds) for t, ds in typemap.items()}
        existing = {origin}
        for (o, t, d) in parsed:
            n = o
            while n is not None:
                existing.add(n)
                if n == origin:
                    break
                n = parent(n)
        ol = label_tuple(origin)
        zone_structs.append({
            "origin": origin,
            "origin_labels": ol,
            "lcount": len(ol),
            "recs": recs,
            "existing": existing,
        })
    return zone_structs


def build_profiles(profiles):
    if not isinstance(profiles, list):
        raise Invalid
    if not (1 <= len(profiles) <= 8):
        raise Invalid
    seen = set()
    out = []
    for p in profiles:
        if not isinstance(p, dict):
            raise Invalid
        if set(p.keys()) != {"id", "max_aliases", "cname", "wildcard"}:
            raise Invalid
        pid = p["id"]
        if not valid_id(pid):
            raise Invalid
        if pid in seen:
            raise Invalid
        seen.add(pid)
        ma = p["max_aliases"]
        if type(ma) is not int or not (0 <= ma <= 64):
            raise Invalid
        cname = p["cname"]
        if cname not in ("follow", "stop"):
            raise Invalid
        wildcard = p["wildcard"]
        if wildcard not in ("rfc", "off", "one-label"):
            raise Invalid
        out.append({"id": pid, "max_aliases": ma, "cname": cname, "wildcard": wildcard})
    return out


def build_queries(queries):
    if not isinstance(queries, list):
        raise Invalid
    if len(queries) > 20:
        raise Invalid
    seen = set()
    out = []
    for q in queries:
        if not isinstance(q, dict):
            raise Invalid
        if set(q.keys()) != {"id", "name", "type", "cost"}:
            raise Invalid
        qid = q["id"]
        if not valid_id(qid):
            raise Invalid
        if qid in seen:
            raise Invalid
        seen.add(qid)
        name = valid_name(q["name"])
        if name is None:
            raise Invalid
        t = q["type"]
        if not isinstance(t, str) or t not in TYPES:
            raise Invalid
        cost = q["cost"]
        if type(cost) is not int or not (1 <= cost <= 1000):
            raise Invalid
        out.append({"id": qid, "name": name, "type": t, "cost": cost})
    return out


def build_observations(observations, query_ids, profile_ids):
    if not isinstance(observations, list):
        raise Invalid
    if len(observations) > 64:
        raise Invalid
    seen = set()
    out = []
    for o in observations:
        if not isinstance(o, dict):
            raise Invalid
        if set(o.keys()) != {"id", "query", "profile", "result"}:
            raise Invalid
        oid = o["id"]
        if not valid_id(oid):
            raise Invalid
        if oid in seen:
            raise Invalid
        seen.add(oid)
        qref = o["query"]
        pref = o["profile"]
        if qref not in query_ids or pref not in profile_ids:
            raise Invalid
        res = o["result"]
        if not isinstance(res, dict):
            raise Invalid
        if res.get("status") == "timeout":
            if set(res.keys()) != {"status"}:
                raise Invalid
            out.append({"id": oid, "query": qref, "profile": pref,
                        "timeout": True, "rcode": None, "answer": None})
        elif res.get("status") == "response":
            if set(res.keys()) != {"status", "rcode", "answer"}:
                raise Invalid
            rcode = res["rcode"]
            if not isinstance(rcode, str) or rcode not in RCODES:
                raise Invalid
            ans = res["answer"]
            if not isinstance(ans, list):
                raise Invalid
            if len(ans) > 128:
                raise Invalid
            recs = [parse_record(r) for r in ans]
            out.append({"id": oid, "query": qref, "profile": pref,
                        "timeout": False, "rcode": rcode, "answer": recs})
        else:
            raise Invalid
    return out


# ---------------------------------------------------------------- resolver
def select_zone(cur, zones_sorted):
    cl = label_tuple(cur)
    for z in zones_sorted:
        ol = z["origin_labels"]
        if len(ol) <= len(cl):
            if not ol or cl[-len(ol):] == ol:
                return z
    return None


def select_source(z, cur, mode):
    existing = z["existing"]
    if cur in existing:
        return cur
    if mode == "off":
        return None
    n = parent(cur)
    encl = None
    while n is not None:
        if n in existing:
            encl = n
            break
        n = parent(n)
    if encl is None:
        return None
    cand = "*." if encl == "." else "*." + encl
    if cand not in existing:
        return None
    if mode == "one-label":
        if label_count(cur) != label_count(encl) + 1:
            return None
    return cand


def resolve(query, profile, zones_sorted):
    cur = query["name"]
    qtype = query["type"]
    seen = set()
    aliases = 0
    answer = []
    trace = []

    while True:
        trace.append(cur)
        if cur in seen:
            return "SERVFAIL", "LOOP", cur, answer, trace
        seen.add(cur)

        z = select_zone(cur, zones_sorted)
        if z is None:
            if aliases == 0:
                return "REFUSED", "OUTSIDE", cur, answer, trace
            return "NOERROR", "EXTERNAL", cur, answer, trace

        source = select_source(z, cur, profile["wildcard"])
        if source is None:
            return "NXDOMAIN", "NXDOMAIN", cur, answer, trace

        owner = cur
        rrsets = z["recs"].get(source, {})

        if qtype == "CNAME":
            if "CNAME" in rrsets:
                for data in rrsets["CNAME"]:
                    answer.append({"owner": owner, "type": "CNAME", "data": data})
                return "NOERROR", "ANSWER", cur, answer, trace
            return "NOERROR", "NODATA", cur, answer, trace

        if "CNAME" in rrsets:
            target = rrsets["CNAME"][0]
            if profile["cname"] == "stop":
                answer.append({"owner": owner, "type": "CNAME", "data": target})
                return "NOERROR", "CNAME_STOP", cur, answer, trace
            if aliases == profile["max_aliases"]:
                return "SERVFAIL", "LIMIT", cur, answer, trace
            answer.append({"owner": owner, "type": "CNAME", "data": target})
            aliases += 1
            cur = target
            continue

        if qtype in rrsets:
            for data in rrsets[qtype]:
                answer.append({"owner": owner, "type": qtype, "data": data})
            return "NOERROR", "ANSWER", cur, answer, trace
        return "NOERROR", "NODATA", cur, answer, trace


# ---------------------------------------------------------------- optimizer
def _enum_subsets(items):
    res = [(0, 0, 0, ())]
    for i, (qid, mask, cost) in enumerate(items):
        add = []
        for (cm, cc, cnt, idx) in res:
            add.append((cm | mask, cc + cost, cnt + 1, idx + (i,)))
        res = res + add
    return res


def optimal_basis(queries, pids, sig):
    pairs = []
    for i in range(len(pids)):
        for j in range(i + 1, len(pids)):
            pairs.append((pids[i], pids[j]))

    cov = []
    universe = 0
    for q in queries:
        m = 0
        qid = q["id"]
        for k, (a, b) in enumerate(pairs):
            if sig[(qid, a)] != sig[(qid, b)]:
                m |= 1 << k
        if m:
            cov.append((qid, m, q["cost"]))
            universe |= m

    if universe == 0:
        return [], 0, 0

    mid = len(cov) // 2
    A = cov[:mid]
    B = cov[mid:]
    subA = _enum_subsets(A)
    subB = _enum_subsets(B)

    best = None
    best_basis = ()
    for (mA, cA, nA, iA) in subA:
        for (mB, cB, nB, iB) in subB:
            if (mA | mB) == universe:
                key = (cA + cB, nA + nB)
                if best is None or key < best:
                    best = key
                    chosen = list(iA) + [mid + i for i in iB]
                    best_basis = tuple(chosen)

    qids = sorted(cov[i][0] for i in best_basis)
    cost = sum(cov[i][2] for i in best_basis)
    return qids, cost, len(qids)


# ---------------------------------------------------------------- main analyze
def analyze(raw):
    if len(raw) > MAX_BYTES:
        raise Invalid
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid
    try:
        doc = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_float=_parse_float, parse_constant=_parse_constant)
    except (ValueError, RecursionError):
        raise Invalid

    if not check_depth(doc):
        raise Invalid

    if not isinstance(doc, dict):
        raise Invalid
    if set(doc.keys()) != {"zones", "profiles", "queries", "observations"}:
        raise Invalid

    zones = build_zones(doc["zones"])
    profiles = build_profiles(doc["profiles"])
    queries = build_queries(doc["queries"])
    query_ids = set(q["id"] for q in queries)
    profile_ids = set(p["id"] for p in profiles)
    observations = build_observations(doc["observations"], query_ids, profile_ids)

    zones_sorted = sorted(zones, key=lambda z: -z["lcount"])

    run_map = {}
    sig = {}
    for q in queries:
        for p in profiles:
            rcode, term, final, answer, trace = resolve(q, p, zones_sorted)
            run = {
                "query": q["id"],
                "profile": p["id"],
                "rcode": rcode,
                "termination": term,
                "final_name": final,
                "answer": answer,
                "trace": trace,
            }
            run_map[(q["id"], p["id"])] = run
            sig[(q["id"], p["id"])] = (
                rcode,
                frozenset((r["owner"], r["type"], r["data"]) for r in answer),
            )

    runs = [run_map[k] for k in sorted(run_map)]

    audits = []
    for obs in sorted(observations, key=lambda o: o["id"]):
        if obs["timeout"]:
            audits.append({"id": obs["id"], "verdict": "unobserved", "different": []})
            continue
        obs_sig = (obs["rcode"],
                   frozenset(obs["answer"]))
        run_sig = sig[(obs["query"], obs["profile"])]
        if obs_sig == run_sig:
            audits.append({"id": obs["id"], "verdict": "match", "different": []})
        else:
            different = []
            if obs_sig[0] != run_sig[0]:
                different.append("rcode")
            if obs_sig[1] != run_sig[1]:
                different.append("answer")
            audits.append({"id": obs["id"], "verdict": "divergence", "different": different})

    # equivalence classes
    pids_all = sorted(p["id"] for p in profiles)
    qorder = sorted(queries, key=lambda q: q["id"])
    groups = {}
    for p in profiles:
        pid = p["id"]
        vec = tuple(sig[(q["id"], pid)] for q in qorder)
        groups.setdefault(vec, []).append(pid)
    classes = sorted([sorted(v) for v in groups.values()])

    basis, cost, count = optimal_basis(queries, pids_all, sig)

    return {
        "runs": runs,
        "audits": audits,
        "diagnostic": {
            "equivalence": classes,
            "basis": basis,
            "cost": cost,
            "count": count,
        },
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        result = analyze(raw)
    except Invalid:
        sys.stdout.write('{"error":"invalid-input"}\n')
        return
    sys.stdout.write(json.dumps(result, separators=(",", ":")) + "\n")


if __name__ == "__main__":
    main()
